<script setup lang="ts">
import {ref,watch,onBeforeUnmount} from 'vue';import AccountingSelect from './AccountingSelect.vue';import AdminDialog from '../../AdminDialog.vue';import AccountingApprovalPanel from './AccountingApprovalPanel.vue';
const props=defineProps<{openId?:number;company:number;accounts:any[];csrf?:string}>(),emit=defineEmits(['notice']);const data=ref<any>(null),selected=ref<any>(null),stage=ref(''),page=ref(1),loading=ref(false),error=ref('');let generation=0;
const money=(v:any)=>Number(v||0).toLocaleString('en-PK',{minimumFractionDigits:2,maximumFractionDigits:2});
async function openTarget(){if(!props.openId)return;try{const r=await fetch('/accounting/api/approvals?company_id='+props.company+'&id='+props.openId,{headers:{Accept:'application/json'}});const d=await r.json();if(!r.ok)throw Error(d.message);selected.value=d.entries?.data?.[0]||null;if(!selected.value)error.value='This approval is no longer available.';}catch(e){error.value=(e as Error).message;}}
async function load(){const gen=++generation;loading.value=true;error.value='';try{const r=await fetch('/accounting/api/approvals?'+new URLSearchParams({company_id:String(props.company),stage:stage.value,page:String(page.value)}),{headers:{Accept:'application/json'}});const d=await r.json();if(!r.ok)throw Error(d.message);if(gen===generation)data.value=d;}catch(e){if(gen===generation)error.value=(e as Error).message;}finally{if(gen===generation)loading.value=false;}}
watch(()=>props.company,()=>{page.value=1;selected.value=null;void load();void openTarget();},{immediate:true});onBeforeUnmount(()=>generation++);
</script>
<template><section><div class="ac-section-heading"><div><h2>Approvals</h2><p class="muted">Review pending documents before they affect the ledger.</p></div><button class="button" :disabled="loading" @click="load">Refresh</button></div><p v-if="error" class="notice admin-error" role="alert">{{error}}</p><form class="ac-filters" @submit.prevent="page=1;load()"><label>Approval stage<AccountingSelect><select v-model="stage"><option value="">All stages</option><option v-for="(label,key) in data?.stages||{}" :key="key" :value="key">{{label}}</option></select></AccountingSelect></label><button class="button" :disabled="loading">Apply filters</button></form><p v-if="loading" role="status">Loading approval queue...</p><template v-else-if="data"><p v-if="!data.enabled" class="ac-help">Approval workflow is currently disabled in Company books. Existing approval history is retained.</p><div class="ac-table-wrap"><table class="ac-finance-table"><thead><tr><th>Document</th><th>Date</th><th>Party / description</th><th>Stage</th><th class="numeric">Amount</th><th></th></tr></thead><tbody><tr v-for="entry in data.entries.data" :key="entry.id"><td><strong>{{entry.document.number}}</strong><small>{{entry.document_type==='payment'?'Invoice payment':entry.document_type==='invoice'?'Invoice':'Journal / voucher'}}</small></td><td>{{entry.document.posting_date}}</td><td>{{entry.document.party_name||entry.document.voucher_person||entry.document.remarks||'—'}}</td><td><span class="ac-badge" :class="entry.stage==='posted'?'active':'inactive'">{{entry.stage_label}}</span></td><td class="numeric">{{entry.document.total_currency}} {{money(entry.document.total)}}</td><td><button class="button" @click="selected=entry">{{entry.can_approve?'Review & approve':'View review'}}</button></td></tr><tr v-if="!data.entries.data.length"><td colspan="6" class="ac-empty-small">No approval records match these filters.</td></tr></tbody></table></div><div class="ac-pagination"><span>Page {{page}} of {{data.entries.last_page}} · {{data.entries.total}} records</span><button class="button" :disabled="page<=1||loading" @click="page--;load()">Previous</button><button class="button" :disabled="page>=data.entries.last_page||loading" @click="page++;load()">Next</button></div></template>
<AdminDialog v-if="selected" :title="selected.document.number" dialog-class="ac-dialog ac-review-dialog" @close="selected=null"><p>{{selected.document.party_name||selected.document.voucher_person||selected.document.remarks}}</p><p><strong>Amount: {{selected.document.total_currency}} {{money(selected.document.total)}}</strong> · {{selected.document.posting_date}}</p><p v-if="selected.document.currency">Transaction currency: {{selected.document.currency}} · Rate: {{selected.document.exchange_rate}}</p><div v-if="selected.document.lines" class="ac-table-wrap"><table class="ac-finance-table"><thead><tr><th>Account / item</th><th>Description</th><th class="numeric">Debit / amount</th><th class="numeric">Credit</th></tr></thead><tbody><tr v-for="(line,index) in selected.document.lines" :key="index"><td>{{line.account_name||accounts.find(a=>a.id===line.account_id)?.name}}</td><td>{{line.description}}</td><td class="numeric">{{money(line.base_debit??line.debit??line.amount)}}</td><td class="numeric">{{line.credit?money(line.base_credit??line.credit):'—'}}</td></tr></tbody></table></div><dl v-if="selected.document.payload"><dt>Invoice party</dt><dd>{{selected.document.party_name}}</dd><dt>Cash / bank account</dt><dd>{{accounts.find(a=>a.id===selected.document.payload.bank_account_id)?.name}}</dd><dt>Reference</dt><dd>{{selected.document.payload.reference}}</dd></dl><AccountingApprovalPanel :company="company" :type="selected.document_type" :document-id="selected.document_id" :version="selected.document.version" :csrf="csrf" @notice="emit('notice',$event)" @changed="selected=null;load()"/></AdminDialog></section></template>
